      "paper": {
        "corpusId": "272086500",
        "title": "Threats and Opportunities of Students’ Use Of AI-Integrated Technology (ChatGPT) in Online Higher Education: Saudi Arabian Educational Technologists’ Perspectives",
        "authors": [
          "Mesfer Mihmas Mesfer Aldawsari",
          "Nouf Rashed Ibrahim Almohish"
        ],
        "openAccessInfo": {
          "license": "CCBY",
          "status": "GOLD",
          "disclaimer": "Notice: This snippet is extracted from the open access paper or abstract available at https://api.unpaywall.org/v2/10.19173/irrodl.v25i3.7642?email=<INSERT_YOUR_EMAIL> or https://doi.org/10.19173/irrodl.v25i3.7642, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
        }
